StructuredTextModel.Text:
//------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ 
//	NAME: 	HE_FrekvOmf_ATV320_Wrapper
//	CREATOR:	                                                                                                                                                                                                                                                  
//                                                                                                                                                                                                                                                                                                                            
//------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ 
//  VERSION LOG:                                                                                                                                                                                                                                                                                                   
//	VERSION			DATE				SIGN						DESCRIPTION                                                                                                                                                                                                                                 
//  1.0.0				31.01.2025		JMD							Draft
//===============================================================================================================================
//
//		DESCRIPTION:
//
//		FUNCTION:
//
//
//===============================================================================================================================

(*************************************************************************
 *	Update Inputs
 *************************************************************************)
 
// Config Parameter
Ext_VFD.EXT_Engineering.Auto_Visible:= 							Cfg_Auto_InUse;
Ext_VFD.EXT_General.LocationIndex[0]:=							Cfg_MainLocation; //First index / main location is forced; remaining tree optional can be set in SCADA
Ext_VFD.EXT_Engineering.ReverseRunning_Visible:=			FALSE;
Ext_VFD.EXT_Engineering.LCfg_Autotune_Visible:=			FALSE;
Ext_VFD.EXT_Engineering.LCfg_MotorData_Visible:=			FALSE;
Ext_VFD.EXT_Engineering.LCfg_RampTime_Visible:=			FALSE;
 
// Input Parmeter
FB_VFD_Logic.Cfg_ControllerTAG:=				Cfg_ControllerTAG;
FB_VFD_Logic.Cfg_ProcessTAG:=					Cfg_ProcessTAG;
FB_VFD_Logic.Inp_AutoRunFwd:=				Inp_AutoStartRef;
FB_VFD_Logic.Inp_AutoSpeedRef:=				Inp_AutoSpeedRef;
FB_VFD_Logic.Inp_Interlock := 					Inp_Interlock;
FB_VFD_Logic.Cfg_Interlock_InUse:=			Cfg_Interlock_InUse;
FB_VFD_Logic.Inp_Interlock:=						Inp_Interlock;
FB_VFD_Logic.Cfg_Interlock_InUse:=			Cfg_Interlock_InUse;
FB_VFD_Logic.Cfg_STO_InUse:=					Cfg_STO_InUse;
FB_VFD_Logic.Inp_AlmSuppress:=				Inp_AlmSuppress;
FB_VFD_Logic.Inp_AlmSuppressDesc:= 		Inp_AlmSuppressDesc;
FB_VFD_Logic.Inp_ComFault :=					HE_CommFault(PORT:=Cfg_EIP_Interface, IP:=Cfg_DriveIP);

// Fieldbus Input
FB_VFD_Logic.Inp_Online :=						TRUE;
FB_VFD_Logic.Inp_Ready := 						TRUE;
FB_VFD_Logic.Inp_RunningFwd := 				Ext_VFD_Input.Par100.Bit[1] AND Ext_VFD_Input.Par100.Bit[6] AND Ext_VFD_Input.Par100.Bit[7]; //Running fwd
FB_VFD_Logic.Inp_RunningRev :=				Ext_VFD_Input.Par100.Bit[1] AND Ext_VFD_Input.Par100.Bit[6] AND NOT Ext_VFD_Input.Par100.Bit[7]; //Running rev
FB_VFD_Logic.Inp_Remote :=						Ext_VFD_Input.Par100.Bit[0];
FB_VFD_Logic.Inp_Error  := 							Ext_VFD_Input.Par110.Wrd > 0;
FB_VFD_Logic.Inp_Warning := 					Ext_VFD_Input.Par111.Wrd > 0;
FB_VFD_Logic.Inp_LocalStop := 					FALSE;
FB_VFD_Logic.Inp_VoltageEnabled :=			TRUE;
FB_VFD_Logic.Inp_STO :=	 						FALSE;
FB_VFD_Logic.Inp_ActSpeed := 					ScaleTrans(SclIn:=WORD_TO_INT(Ext_VFD_Input.Par302.Wrd),
																				  	X0:=0,
																				  	Y0:=0,
																				  	X1:=10000,
																				  	Y1:=100);

(*************************************************************************
 *	VFD Power, Current, Energy
 *************************************************************************)
 
FB_VFD_Logic.Inp_Power:=  	(INT_TO_REAL(DWORD_TO_INT(Ext_VFD_Input.Par351.DWrd)) / 1000.0); //kW
FB_VFD_Logic.Inp_Energy:=		(INT_TO_REAL(DWORD_TO_INT(Ext_VFD_Input.Par352.DWrd)) / 1000.0); //kWh
FB_VFD_Logic.Inp_Current:= 	WORD_TO_REAL(Ext_VFD_Input.Par335.Wrd) / 10; //A

(*************************************************************************
 *	Runtime Statistics
 *************************************************************************)
 
FB_VFD_Logic.Inp_VFD_TotalOnTime :=		DWORD_TO_ULINT(Ext_VFD_Input.Par354.DWrd);	
FB_VFD_Logic.Inp_VFD_TotalRunTime :=		DWORD_TO_ULINT(Ext_VFD_Input.Par353.DWrd);
	
(*************************************************************************
 *	State and error
 *************************************************************************)
	
FB_VFD_Logic.Inp_Active_Error:= 		HE_CIM500_Drive_Fault(Inp_VFDErrorCode:=Ext_VFD_Input.Par110.Wrd, Cfg_Delimiter:=' - ', Cfg_Composition:=7);
FB_VFD_Logic.Inp_Active_Warning:= 	HE_CIM500_Drive_Fault(Inp_VFDErrorCode:=Ext_VFD_Input.Par111.Wrd, Cfg_Delimiter:=' - ', Cfg_Composition:=7);
FB_VFD_Logic.Inp_Actual_State:=		HE_CIM500_Drive_State(Inp_VFDStateCode:=Ext_VFD_Input.Par103.Wrd, Cfg_Delimiter:=' - ', Cfg_Composition:=7);

(*************************************************************************
 *	Execute VFD Logic
 *************************************************************************)
 
FB_VFD_Logic(Ext_VFD:=Ext_VFD, 
						Int_Alarm:=Int_Alarm);

(*************************************************************************
 *	Update Outputs
 *************************************************************************)

// Output Parameters
Sts_Alarm:=					FB_VFD_Logic.Sts_AlarmTriggered;
Sts_AvailableAuto := 	FB_VFD_Logic.Sts_AvailableAuto;
Sts_Interlock := 			FB_VFD_Logic.Sts_Interlock;
Sts_RunningFwd := 		FB_VFD_Logic.Inp_RunningFwd;

// Fieldbus Output
Ext_VFD_Output.Par1 				:= TRUE; //Set remote
Ext_VFD_Output.Par2 				:= FB_VFD_Logic.Out_RunFwd AND FB_VFD_Logic.Out_Enable; //Run fwd
Ext_VFD_Output.Par3 				:= TRUE; //Copy to local
Ext_VFD_Output.Par8 				:= FB_VFD_Logic.Out_FaultReset; // Fault Reset
Ext_VFD_Output.Par20.Wrd 	:= 1; //Constanst freq
Ext_VFD_Output.Par21.Wrd		:= 0; //Auto control

Ext_VFD_Output.Par30.Wrd 	:=	REAL_TO_WORD(ScaleTrans(
															SclIn:=FB_VFD_Logic.Out_SpeedRef,
															X0:= 0.0,
															Y0:= 0.0,
															X1:= 100.0,
															Y1:= 10000.0));
